/* Typed access to the real menu. menu.json is generated by scripts/gen-menu.mjs from design/data/menu.js:
   regenerate, never edit by hand. */
import raw from "./menu.json" with { type: "json" };

export type TagId = "hit" | "new" | "veg" | "hot" | "out";
export type Course = "starter" | "salad" | "main" | "side" | "sauce" | "dessert" | "drink" | "addon" | "breakfast";
export type AllergenId =
  | "gluten" | "crustaceans" | "eggs" | "fish" | "peanuts" | "soy" | "milk"
  | "nuts" | "celery" | "mustard" | "sesame" | "sulphites" | "lupin" | "molluscs";

export interface Category { id: string; n: string; course: Course }

export interface Dish {
  id: string;
  n: string;          // name
  cat: string;        // category id ("obedno" for lunch items)
  course: Course;
  comp: string;       // composition text ("" when unknown)
  g: string;          // weight / unit text, e.g. "350 гр."
  p: number;          // price in EUR
  lv?: number;        // original price in BGN
  site_eur?: number;
  t: TagId[];         // hit/new are sample tags; veg/hot derived from comp (kitchen confirms)
  al: AllergenId[];   // derived from comp (kitchen confirms)
  noOnion: boolean;
  share: boolean;
  per100?: boolean;   // price is per 100 g (Black Angus steaks)
  priceNote?: string;
  protein?: number;   // nutrition data: not in the data yet
  kcal?: number;
  /* lunch-only fields */
  group?: string;
  lunch?: boolean;
}

export interface LunchRaw { id: string; group: string; n: string; p: number | null }

export interface Menu {
  updated: string;
  source: string;
  cats: Category[];
  items: Dish[];
  lunch: { date: string; dayName: string; items: LunchRaw[] };
}

export const MENU = raw as unknown as Menu;
